using HRM.Models.Recruitment;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace HRM.Api.Data.EntityConfigurations;public sealed class RecruitmentOfficialTemplatesMapping:IEntityTypeConfiguration<RecruitmentOfficialTemplate>{public void Configure(EntityTypeBuilder<RecruitmentOfficialTemplate>b){b.ToTable("RM_RecruitmentOfficialTemplates");b.HasKey(x=>x.Id);b.Property(x=>x.TemplateCode).HasMaxLength(100).IsRequired();b.Property(x=>x.Name).HasMaxLength(250).IsRequired();b.Property(x=>x.SourceUrl).HasMaxLength(2048).IsRequired();b.Property(x=>x.SourceSha256).HasMaxLength(64).IsRequired();b.Property(x=>x.TemplateDefinitionJson).HasMaxLength(16000).IsRequired();b.Property(x=>x.PositionCategory).HasMaxLength(100).IsRequired();b.Property(x=>x.Language).HasMaxLength(10).IsRequired();b.Property(x=>x.Direction).HasMaxLength(3).IsRequired();b.Property(x=>x.VerificationStatus).HasMaxLength(40).IsRequired();b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>new{x.RecruitmentPolicyVersionId,x.TemplateCode,x.PositionCategory}).IsUnique();b.HasOne<RecruitmentPolicyVersion>().WithMany().HasForeignKey(x=>x.RecruitmentPolicyVersionId).OnDelete(DeleteBehavior.Restrict);b.HasOne<global::HRM.Models.DmsDocument>().WithMany().HasForeignKey(x=>x.SourceDocumentId).OnDelete(DeleteBehavior.Restrict);}}
